*** Add File: /work/src/game/boardCode.ts
+import { BOARD_SIZES, type BoardSize } from "./constants.js";
+
+const PARK_MILLER_MODULUS = 2_147_483_647;
+const PARK_MILLER_RANGE = PARK_MILLER_MODULUS - 1;
+const PARK_MILLER_MULTIPLIER = 16_807;
+const BOARD_CODE_PATTERN = /^np1-(4|6|8|10|12|14|16)-([1-9][0-9]*)$/;
+
+export interface Board {
+  readonly boardCode: string;
+  readonly size: BoardSize;
+  readonly deck: readonly number[];
+}
+
+export interface ParsedBoardCode {
+  readonly boardCode: string;
+  readonly size: BoardSize;
+  readonly seed: number;
+}
+
+export function parseBoardCode(code: string): ParsedBoardCode | null {
+  const match = BOARD_CODE_PATTERN.exec(code);
+  if (match === null) return null;
+  const size = Number(match[1]);
+  const seed = Number(match[2]);
+  if (!isBoardSize(size) || !Number.isSafeInteger(seed) || seed > PARK_MILLER_RANGE) {
+    return null;
+  }
+  return { boardCode: code, size, seed };
+}
+
+export function isBoardSize(value: number): value is BoardSize {
+  return BOARD_SIZES.some((size) => size === value);
+}
+
+export function generateDeck(size: BoardSize, seed: number): readonly number[] {
+  const deck: number[] = [];
+  for (let face = 0; face < (size * size) / 2; face += 1) {
+    deck.push(face, face);
+  }
+
+  let generatorState = seed;
+  const draw = (bound: number): number => {
+    const limit = Math.floor(PARK_MILLER_RANGE / bound) * bound;
