  };

  const selectSize = (size: number): void => {
    if (!BOARD_SIZES.some((candidate) => candidate === size)) return;
    freshGame(size as BoardSize);
  };

  const newGame = (): void => freshGame(gameRef.current.board.size);
  const restart = (): void => {
    const next = createGame(gameRef.current.board.boardCode);
    if (next !== null) replaceGame(next, false, "");
  };

  const activate = (index: number): void => {
    if (pausedRef.current) return;
    clockFlush.current();
    const previous = gameRef.current;
    const next = activateCard(previous, index);
    if (next === previous) return;
    if (!previous.started && next.started) {
      clockCursor.current = { lastTimeMs: performance.now(), fractionalMs: 0 };
    }
    commitGame(next);
    announceTurn(previous, next, announce);
    if (!isWon(previous) && isWon(next)) recordBest(next, bestScoresRef, setBestScores);
    if (!isWon(previous) && isWon(next)) setCelebrating(true);
  };

  const loadBoard = (code: string): void => {
    const next = createGame(code.trim());
    if (next === null) {
      setReproductionStatus("Invalid board code.");
      announce("Invalid board code.");
      return;
    }
    replaceGame(next, false, "Loaded board.");
  };

  const loadSnapshot = (text: string): void => {
    const next = decodeSnapshot(text);
    if (next === null) {
      setReproductionStatus("Invalid snapshot.");
      announce("Invalid snapshot.");
      return;
    }
    const isPaused = !isWon(next);
    const status = isPaused
      ? "Loaded snapshot. Select Resume to continue."
      : "Loaded completed snapshot.";
    replaceGame(next, isPaused, status);
  };

  const exportSnapshot = (): string => {
    clockFlush.current();
    return encodeSnapshot(gameRef.current);
  };

  const resume = (): void => {
    if (!pausedRef.current) return;
    pausedRef.current = false;
    clockCursor.current = { lastTimeMs: performance.now(), fractionalMs: 0 };
    setPaused(false);
  };

  const clearCelebration = (): void => setCelebrating(false);
  const bestMoves = bestScores[game.board.size] ?? null;

  return {
    game,
    paused,
    bestMoves,
    dealRevision,
    announcement,
    reproductionStatus,
    celebrating,
    selectSize,
    newGame,
    restart,
    activate,
    loadBoard,
    loadSnapshot,
    exportSnapshot,
    resume,
    clearCelebration,
  };
}

function createInitialGame(): GameState {
  const size = readSavedSize() ?? 4;
  const game = createGame(`np1-${size}-${createSeed()}`);
  if (game === null) throw new Error("Could not create a starting deal.");
  return game;
}

function commitGame(next: GameState, ref?: { current: GameState }, setter?: (game: GameState) => void): void {
  if (ref !== undefined && setter !== undefined) {
    ref.current = next;
    setter(next);
  }
}

function advanceCurrent(
  ref: { current: GameState },
  setter: (game: GameState) => void,
  milliseconds: number,
): GameState {
  const next = { ...ref.current, ...{ elapsedMs: ref.current.elapsedMs } };
  const advanced = advanceState(next, milliseconds);
  ref.current = advanced;
  setter(advanced);
  return advanced;
}

function advanceState(state: GameState, milliseconds: number): GameState {
  return advanceGameState(state, milliseconds);
}

function announceTurn(previous: GameState, next: GameState, announce: (text: string) => void): void {
  if (next.moves === previous.moves) return;
  if (next.matched.length > previous.matched.length) {
    const pairs = matchedPairs(next);
    if (isWon(next)) {
      announce(`Pair found. All pairs found in ${next.moves} moves and ${formatTime(next.elapsedMs)}.`);
    } else if (pairs === 1) {
      announce("Pair found. 1 pair matched.");
    } else {
      announce(`Pair found. ${pairs} pairs matched.`);
    }
    return;
  }
  announce("No match. Cards close after a short pause.");
}

function recordBest(
  state: GameState,
  current: { current: BestScores },
  setter: (scores: BestScores) => void,
): void {
  const previous = current.current[state.board.size];
  if (previous !== undefined && previous <= state.moves) return;
  const updated = { ...current.current, [state.board.size]: state.moves };
  current.current = updated;
  setter(updated);
  saveBestScores(updated);
}

function formatTime(milliseconds: number): string {
  const seconds = Math.floor(milliseconds / 1_000);
  const minutes = Math.floor(seconds / 60);
  return `${minutes}:${String(seconds % 60).padStart(2, "0")}`;
}

